// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line keeper.scxml:6
func (p *KeeperPolicy) FirstEnabledTransition(state KeeperState, event KeeperEvent, engine *sce.Engine[KeeperState, KeeperEvent]) (sce.EnabledTransition[KeeperState, sce.HistoryID], bool) {
	switch state {
	case KeeperStateLingering:
		if event == KeeperEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if p.sceTestContext.TimedOut("linger") {
				return sce.EnabledTransition[KeeperState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfKeeper[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	case KeeperStateWatching:
		if event == KeeperEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if p.sceTestContext.TimedOut("patience") {
				return sce.EnabledTransition[KeeperState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfKeeper[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[KeeperState, sce.HistoryID]{}, false
}

